@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap');

:root {
  --primary-dark: #141414;
  --white: #FFFFFF;
  --light-gray: #F5F5F5;
  --medium-gray: #E5E5E5;
  --text-gray: #666666;
  --accent: #4F46E5; /* Indigo/Violet */
  --accent-hover: #4338CA;
  --border-radius-sm: 8px;
  --border-radius-md: 12px;
  --border-radius-lg: 24px;
  --border-radius-pill: 9999px;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
  --transition-fast: 200ms ease;
  --transition-normal: 300ms ease;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: 'Inter', sans-serif;
  color: var(--primary-dark);
  background-color: var(--white);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

a {
  text-decoration: none;
  color: inherit;
}

ul {
  list-style: none;
}

button {
  cursor: pointer;
  border: none;
  background: none;
  font-family: inherit;
}

img {
  max-width: 100%;
  display: block;
}

/* Utilities */
.container {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
}

.text-center {
  text-align: center;
}

.section-padding {
  padding: 96px 0;
}

@media (max-width: 768px) {
  .section-padding {
    padding: 64px 0;
  }
}

.title-lg {
  font-size: 3.5rem;
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.02em;
  margin-bottom: 24px;
}

.title-md {
  font-size: 2.5rem;
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: -0.02em;
  margin-bottom: 16px;
}

.subtitle {
  font-size: 1.25rem;
  color: var(--text-gray);
  margin-bottom: 40px;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 12px 24px;
  border-radius: var(--border-radius-pill);
  font-weight: 500;
  font-size: 1rem;
  transition: all var(--transition-fast);
}

.btn-primary {
  background-color: var(--accent);
  color: var(--white);
  box-shadow: 0 4px 14px 0 rgba(79, 70, 229, 0.39);
}

.btn-primary:hover {
  background-color: var(--accent-hover);
  transform: translateY(-1px);
  box-shadow: 0 6px 20px rgba(79, 70, 229, 0.23);
}

.btn-secondary {
  background-color: var(--light-gray);
  color: var(--primary-dark);
}

.btn-secondary:hover {
  background-color: var(--medium-gray);
}

/* Announcement Bar */
.announcement-bar {
  background-color: var(--primary-dark);
  color: var(--white);
  text-align: center;
  padding: 12px 24px;
  font-size: 0.875rem;
  font-weight: 500;
}

.announcement-bar a {
  text-decoration: underline;
}

/* Header */
header {
  padding: 24px 0;
  position: sticky;
  top: 0;
  background-color: rgba(255, 255, 255, 0.9);
  backdrop-filter: blur(8px);
  z-index: 100;
  border-bottom: 1px solid var(--light-gray);
}

.header-inner {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.logo {
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  display: flex;
  align-items: center;
  gap: 8px;
}

.logo-icon {
  width: 32px;
  height: 32px;
  background-color: var(--accent);
  border-radius: 8px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.logo-icon svg {
  width: 20px;
  height: 20px;
  fill: var(--white);
}

.nav-links {
  display: flex;
  gap: 32px;
  align-items: center;
}

.nav-links a {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--text-gray);
  transition: color var(--transition-fast);
}

.nav-links a:hover {
  color: var(--primary-dark);
}

.mobile-menu-btn {
  display: none;
  font-size: 1.5rem;
  background: none;
  border: none;
  cursor: pointer;
}

@media (max-width: 768px) {
  .nav-links {
    display: none;
  }
  .mobile-menu-btn {
    display: block;
  }
  .title-lg {
    font-size: 2.5rem;
  }
  .title-md {
    font-size: 2rem;
  }
}

/* Hero Section */
.hero {
  padding: 120px 0 80px;
  text-align: center;
}

.hero .hero-content {
  max-width: 800px;
  margin: 0 auto;
}

.hero-actions {
  display: flex;
  gap: 16px;
  justify-content: center;
  margin-top: 40px;
}

/* Trusted By */
.trusted-by {
  padding: 40px 0;
  overflow: hidden;
  border-top: 1px solid var(--light-gray);
  border-bottom: 1px solid var(--light-gray);
  background-color: var(--light-gray);
}

.trusted-title {
  text-align: center;
  font-size: 0.875rem;
  color: var(--text-gray);
  margin-bottom: 24px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.marquee-container {
  display: flex;
  width: 100%;
  overflow: hidden;
}

.marquee {
  display: flex;
  flex-shrink: 0;
  animation: scroll-left 30s linear infinite;
  align-items: center;
  gap: 64px;
  padding: 0 32px;
}

.marquee.reverse {
  animation: scroll-right 30s linear infinite;
}

.marquee img {
  height: 32px;
  opacity: 0.6;
  filter: grayscale(100%);
  transition: all var(--transition-fast);
}

.marquee img:hover {
  opacity: 1;
  filter: grayscale(0%);
}

@keyframes scroll-left {
  0% { transform: translateX(0); }
  100% { transform: translateX(-100%); }
}

@keyframes scroll-right {
  0% { transform: translateX(-100%); }
  100% { transform: translateX(0); }
}

/* Stats Section */
.stats-section {
  background-color: var(--primary-dark);
  color: var(--white);
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 40px;
  text-align: center;
}

.stat-item .stat-number {
  font-size: 4rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 8px;
  color: var(--accent);
}

.stat-item .stat-label {
  font-size: 1.125rem;
  color: #A3A3A3;
  font-weight: 500;
}

@media (max-width: 768px) {
  .stats-grid {
    grid-template-columns: 1fr;
    gap: 48px;
  }
}

/* Search Features Section */
.search-features {
  background-color: var(--light-gray);
}

.tabs-container {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-bottom: 32px;
  flex-wrap: wrap;
}

.tab-btn {
  padding: 12px 24px;
  border-radius: var(--border-radius-pill);
  font-weight: 500;
  color: var(--text-gray);
  background-color: var(--white);
  transition: all var(--transition-fast);
  box-shadow: var(--shadow-sm);
}

.tab-btn.active {
  background-color: var(--primary-dark);
  color: var(--white);
}

.tab-btn:hover:not(.active) {
  background-color: var(--medium-gray);
}

.filters-container {
  display: flex;
  gap: 12px;
  overflow-x: auto;
  padding-bottom: 16px;
  margin-bottom: 40px;
  scrollbar-width: none; /* Firefox */
}

.filters-container::-webkit-scrollbar {
  display: none; /* Chrome, Safari, Opera */
}

.filter-pill {
  padding: 8px 16px;
  border-radius: var(--border-radius-pill);
  border: 1px solid var(--medium-gray);
  background-color: var(--white);
  color: var(--primary-dark);
  font-size: 0.875rem;
  font-weight: 500;
  white-space: nowrap;
  transition: all var(--transition-fast);
}

.filter-pill.active {
  background-color: var(--accent);
  color: var(--white);
  border-color: var(--accent);
}

.filter-pill:hover:not(.active) {
  border-color: var(--primary-dark);
}

.grid-content {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 24px;
  transition: opacity var(--transition-normal);
}

.screenshot-card {
  background-color: var(--white);
  border-radius: var(--border-radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: transform var(--transition-normal), box-shadow var(--transition-normal);
  cursor: pointer;
}

.screenshot-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}

.screenshot-img-placeholder {
  width: 100%;
  padding-top: 177%; /* ~16:9 for mobile screenshots */
  background: linear-gradient(135deg, #E5E7EB 0%, #F3F4F6 100%);
  position: relative;
}

.screenshot-img-placeholder::after {
  content: 'Screenshot';
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  color: #9CA3AF;
  font-weight: 500;
}

/* Flows Section */
.flows-section {
  background-color: var(--white);
}

.toggle-container {
  display: flex;
  background-color: var(--light-gray);
  border-radius: var(--border-radius-pill);
  padding: 4px;
  width: fit-content;
  margin: 0 auto 48px;
}

.toggle-btn {
  padding: 10px 24px;
  border-radius: var(--border-radius-pill);
  font-weight: 500;
  color: var(--text-gray);
  transition: all var(--transition-fast);
}

.toggle-btn.active {
  background-color: var(--white);
  color: var(--primary-dark);
  box-shadow: var(--shadow-sm);
}

.flows-display {
  background-color: var(--light-gray);
  border-radius: var(--border-radius-lg);
  aspect-ratio: 16/9;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.flow-content {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  color: #9CA3AF;
  font-weight: 500;
  opacity: 0;
  transition: opacity var(--transition-normal);
  pointer-events: none;
}

.flow-content.active {
  opacity: 1;
  pointer-events: auto;
}

/* Tools Section */
.tools-section {
  background-color: var(--primary-dark);
  color: var(--white);
}

.tools-section .subtitle {
  color: #A3A3A3;
}

.tools-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}

.tool-card {
  background-color: #1F1F1F;
  border-radius: var(--border-radius-lg);
  padding: 32px;
  text-align: left;
  border: 1px solid #2D2D2D;
  transition: transform var(--transition-normal);
}

.tool-card:hover {
  transform: translateY(-4px);
}

.tool-icon {
  width: 48px;
  height: 48px;
  background-color: var(--accent);
  border-radius: var(--border-radius-md);
  margin-bottom: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.tool-icon svg {
  width: 24px;
  height: 24px;
  fill: var(--white);
}

.tool-title {
  font-size: 1.25rem;
  font-weight: 600;
  margin-bottom: 12px;
}

.tool-desc {
  color: #A3A3A3;
  line-height: 1.6;
}

@media (max-width: 768px) {
  .tools-grid {
    grid-template-columns: 1fr;
  }
}

/* Testimonials */
.testimonials-section {
  background-color: var(--light-gray);
  overflow: hidden;
}

.testimonials-track {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.testimonial-row {
  display: flex;
  gap: 24px;
  width: max-content;
  animation: scroll-left 40s linear infinite;
}

.testimonial-row:nth-child(even) {
  animation: scroll-right 40s linear infinite;
}

.testimonial-card {
  background-color: var(--white);
  padding: 32px;
  border-radius: var(--border-radius-lg);
  width: 400px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.testimony-text {
  font-size: 1rem;
  color: var(--primary-dark);
  line-height: 1.6;
  flex-grow: 1;
}

.testimony-author {
  display: flex;
  align-items: center;
  gap: 12px;
}

.author-avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background-color: var(--medium-gray);
}

.author-info {
  display: flex;
  flex-direction: column;
}

.author-name {
  font-weight: 600;
  font-size: 0.9375rem;
}

.author-company {
  font-size: 0.875rem;
  color: var(--text-gray);
}

/* CTA Section */
.cta-section {
  text-align: center;
  overflow: hidden;
}

.cta-section .hero-actions {
  margin-bottom: 64px;
}

.app-icons-marquee {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.icon-row {
  display: flex;
  gap: 16px;
  width: max-content;
  animation: scroll-left 30s linear infinite;
}

.icon-row.reverse {
  animation: scroll-right 30s linear infinite;
}

.app-icon {
  width: 64px;
  height: 64px;
  border-radius: 16px;
  background-color: var(--light-gray);
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: var(--shadow-sm);
}

.app-icon svg {
  width: 32px;
  height: 32px;
  fill: var(--text-gray);
}

/* Footer */
footer {
  background-color: var(--primary-dark);
  color: var(--white);
  padding: 80px 0 40px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 48px;
  margin-bottom: 64px;
}

.footer-brand .logo {
  margin-bottom: 16px;
  color: var(--white);
}

.footer-tagline {
  color: #A3A3A3;
  max-width: 280px;
}

.footer-heading {
  font-weight: 600;
  margin-bottom: 24px;
  font-size: 1.125rem;
}

.footer-links {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.footer-links a {
  color: #A3A3A3;
  transition: color var(--transition-fast);
}

.footer-links a:hover {
  color: var(--white);
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 32px;
  border-top: 1px solid #2D2D2D;
  color: #A3A3A3;
  font-size: 0.875rem;
}

.footer-bottom-links {
  display: flex;
  gap: 24px;
}

.footer-bottom-links a:hover {
  color: var(--white);
}

@media (max-width: 768px) {
  .footer-grid {
    grid-template-columns: 1fr 1fr;
  }
  .footer-brand {
    grid-column: 1 / -1;
  }
  .footer-bottom {
    flex-direction: column;
    gap: 16px;
    text-align: center;
  }
}

document.addEventListener('DOMContentLoaded', () => {

  // 1. Stats Counter Animation
  const statNumbers = document.querySelectorAll('.stat-number');
  let hasCounted = false;

  const animateNumbers = () => {
    statNumbers.forEach(stat => {
      const target = parseFloat(stat.getAttribute('data-target').replace(/,/g, ''));
      const formatNumber = (num) => {
        return num.toLocaleString();
      };

      const duration = 2000;
      const stepTime = 20;
      const steps = duration / stepTime;
      const increment = target / steps;

      let current = 0;
      const timer = setInterval(() => {
        current += increment;
        if (current >= target) {
          stat.innerText = formatNumber(target);
          clearInterval(timer);
        } else {
          stat.innerText = formatNumber(Math.floor(current));
        }
      }, stepTime);
    });
  };

  const observerOptions = {
    root: null,
    rootMargin: '0px',
    threshold: 0.5
  };

  const statsObserver = new IntersectionObserver((entries, observer) => {
    entries.forEach(entry => {
      if (entry.isIntersecting && !hasCounted) {
        animateNumbers();
        hasCounted = true;
        observer.unobserve(entry.target);
      }
    });
  }, observerOptions);

  const statsSection = document.querySelector('.stats-section');
  if (statsSection) {
    statsObserver.observe(statsSection);
  }

  // 2. Search Tabs Switching
  const tabBtns = document.querySelectorAll('.tab-btn');
  const gridContents = document.querySelectorAll('.grid-content');

  tabBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      // Remove active class from all tabs
      tabBtns.forEach(t => t.classList.remove('active'));
      // Add active class to clicked tab
      btn.classList.add('active');

      // We would update the grid content here. 
      // For this prototype, we'll just simulate a content change with a fade out/in effect
      const grid = document.querySelector('.grid-content');
      grid.style.opacity = '0';
      setTimeout(() => {
        grid.style.opacity = '1';
      }, 300);
    });
  });

  // 3. Search Filters Switching
  const filterPills = document.querySelectorAll('.filter-pill');

  filterPills.forEach(pill => {
    pill.addEventListener('click', () => {
      // Remove active class from all pills
      filterPills.forEach(p => p.classList.remove('active'));
      // Add active class to clicked pill
      pill.classList.add('active');

      // Simulate content change
      const grid = document.querySelector('.grid-content');
      grid.style.opacity = '0';
      setTimeout(() => {
        grid.style.opacity = '1';
      }, 300);
    });
  });

  // 4. Flows Toggle
  const toggleBtns = document.querySelectorAll('.toggle-btn');
  const flowContents = document.querySelectorAll('.flow-content');

  toggleBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      // Remove active class from all toggles
      toggleBtns.forEach(t => t.classList.remove('active'));
      // Add active class to clicked toggle
      btn.classList.add('active');

      const targetId = btn.getAttribute('data-target');

      // Update contents
      flowContents.forEach(content => {
        if (content.id === targetId) {
          content.classList.add('active');
        } else {
          content.classList.remove('active');
        }
      });
    });
  });

  // Setup endless horizontal scrolling by cloning marquee elements
  const cloneMarquees = () => {
    const marquees = document.querySelectorAll('.marquee, .testimonial-row, .icon-row');
    marquees.forEach(marquee => {
      // Clone the contents to create a seamless loop
      const content = marquee.innerHTML;
      marquee.innerHTML = content + content;
    });
  };

  cloneMarquees();
});
